from markov import Markov
from markov import Markov
from collections import defaultdict

class LessonPlan:
    def __init__(self):
        self.timetable = []

    def add_lesson(self, lesson):
        self.timetable.append(lesson)

    def get_lessons_by_day(self, day):
        return [l for l in self.timetable if l.day == day]

    def generate_schedules(self):
        schedule_sets = defaultdict(list)

        for day in self.get_unscheduled_days():
            schedule_sets[(day, 'beginner')].extend(self.get_available_lessons(day))
            schedule_sets[(day, 'advanced')].extend(self.get_available_lessons(day))

        for day in self.get_unscheduled_days():
            for difficulty in ['beginner', 'advanced']:
                schedule = self.optimize_schedules(schedule_sets[(day, difficulty)])
                self.timetable.append(schedule)

    def optimize_schedules(self, lessons):
        schedule = Markov(lessons)
        return schedule.sample()

    def get_unscheduled_days(self):
        return [d for d in self.get_all_days()
                if not d.is_scheduled()]

