def is_valid_row(row):
  for col in range(9):
    if row[col] != '.':
      possible = 1 << (9 - int(row[col]))
      not_possible = []
      for r in range(9):
        if possible & (1 << (9 - int(board[r][col]))):
          not_possible.append(r)
    else:
        possible -= 1
  return True

def can_guess(g, row, col):
  if is_valid_row(row[:col] + [g] + row[col+1:]) \
   and is_valid_col(board)

def solve():
  for row in range(9):
    for col in range(9):
      if board[row][col] == '.':
        valid = 1
        for g in range(1, 10):
          if can_guess(g, row, col):
            valid += 1
        if valid == 1:
          return False
        guess = random.randint(1, valid)
        for g in range(1, 10):
          if can_guess(g, row, col):
            if guess == 1:
              board[row][col] = str(g)
              break
          guess -= 1
      else:
        pass
      if not is_valid_board(board):
        return False
  return True

