        'id': user_id,
        'name': name,
        'email': email,
        'bio': bio,
    }

    if user_id:
        User.objects(id=user_id).update_one({'$set': user})
        return jsonify({'result': 'ok'})
    else:
        return jsonify({'result': 'error'})

