from collections import Counter

def find_duplicate_elements(integer_array):
    counts = Counter(integer_array)
    duplicates = set()
    for element, count in counts.items():
        if count > 1:
            duplicates.add(element)
    return duplicates

def find_missing_elements(element_array):
    missing_element = {1}
    for element in set(element_array):
        missing_element.discard(element)
    return missing_element

def find_duplicate_and_missing_elements(integer_array):
    integer_array = [int(num) for num in integer_array]
    duplicates = find_duplicate_elements(integer_array)
    missing = find_missing_elements(integer_array)
    return (duplicates, missing)

integer_array = input("Enter a list of integers, separated by spaces: ")
print(find_duplicate_and_missing_elements(integer_array))

