def check_suspicious_file(f):
    suspicious_patterns = [
        "multipart/form-data",
        "Content-Disposition",
        "Content-Length",
        "enctype=\"multipart/form-data\"",
        "Content-Type: application/x-www-form-urlencoded"
    ]

    with open(f, 'r') as fp:
        data = fp.read()
        lines = [line.strip() for line in data.split('\n')]

    for pattern in suspicious_patterns:
        if pattern in data:
            print("Suspicious file found!")
            return True

    return False

def is_xml(f):
    with open(f, 'r') as fp:
        data = fp.read()

    return 'xml' in data

def check_files():
    files = os.listdir(os.getcwd())
    for f in files:
        if check_suspicious_file(f):
            pass

        if is_xml(f):
            pass

