import random

class BreakoutGame:
    def __init__(self):
        self.board = []
        self.empty_rows = []
        self.balls = []
        self.paddles = []
        self.bricks = []

    def start_game(self):
        for i in range(12):
            new_row = [' ' for j in range(14)] if i % 2 == 0 else []
            self.board.append(new_row)
            self.empty_rows.append(new_row)

        for i in range(2):
            self.balls.append({'x': random.randint(1, 13), 'y': 6})

        for i in range(3):
            self.paddles.append({'x': 0, 'y': i + 3})

        self.bricks = self.generate_bricks()
        self.board = self.convert_board()
        print(self.board)

    def convert_board(self):
        result = []
        for i in range(len(self.board)):
            row = []
            for j in range(len(self.board[0])):
                cell = ' '
                if self.board[i][j] == 'B':
                    cell = 'B'
                elif self.board[i][j] == 'P':
                    cell = 'P'
                elif self.board[i][j] == 'E':
                    cell = 'E'
                row.append(cell)
            result.append(row)
        return result

    def generate_bricks(self):
        result = []
        for i in range(14):
            if i % 2 == 0:
                continue
            for j in range(3):
                result.append({'x': i+1, 'y': j+2, 'type': 'B'})
                result.append({'x': i+1, 'y': j+8, 'type': 'B'})
                result.append({'x': i+1, 'y': j+3, 'type': 'B'})
                result.append({'x': i+1, 'y': j+9, 'type': 'B'})

        return result

    def add_element(self, elem):
        self.board[elem['y']][elem['x']] = elem['type']

    def add_ball(self):
        self.balls.append({'x': random.randint(1, 13), 'y': 6})

    def add_paddle(self):
        self.paddles.append({'x': 0, 'y': 3})

    def up_paddle(self, player):
        self.paddles[player]['y'] -= 1
        self.paddles[player]['y'] -= 1
        self.board[self.paddles[player]['y']][self.paddles[player]['x']] = 'P'
        board[self.paddles[player]['y']+1][self.paddles[player]['x']] = 'E'

    def down_paddle(self, player):
        self.paddles[player]['y'] += 1
        self.paddles[player]['y'] += 1
        self.board[self.paddles[player]['y']][self.paddles[player]['x']] = 'P'
        self.board[self.paddles[player]['y']-1][self.paddles[player]['x']] = 'E'

    def shoot(self, player):
        self.balls.append({'x': self.paddles[player]['x']+1, 'y': self.paddles[player]['y']})
        self.add_ball()

breakout = BreakoutGame()
breakout.start_game()

while True:
    breakout.up_paddle(0)
    break

print("Game over")
