import os

def delete_duplicates(directory):
    seen = set()
    deleted = 0
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        if os.path.isfile(filepath):
            with open(filepath, 'rb') as f:
                h = hash(f.read())
            if h in seen:
                os.remove(filepath)
                deleted += 1
            else:
                seen.add(h)

    return deleted

def verify_deletions(directory):
    deleted = 0
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        if os.path.isfile(filepath):
            with open(filepath, 'rb') as f:
                h = hash(f.read())
            if h in seen:
                os.remove(filepath)
                deleted += 1

    return deleted


directory = input("Enter dir path: ")
deleted = delete_duplicates(directory)

if deleted != 0:
    verify_deletions(directory)
    print(f'{deleted} duplicates deleted')
else:
    print('No duplicates found')

